CREATE FUNCTION public.require_active_actor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'ACCOUNT_BLOCKED'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','posts','messages','membership_payments','sharing_claims','notification_preferences','push_devices','service_profiles','service_photos','service_reviews','service_likes','reward_wallets','free_membership_months','post_sharing_evidence','app_settings'] LOOP EXECUTE format('CREATE TRIGGER active_actor_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.require_active_actor()',t); END LOOP; END $$;
CREATE FUNCTION public.guard_post_interest_visibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.post_id IS NOT NULL AND NOT NEW.needs_admin AND EXISTS(SELECT 1 FROM public.posts WHERE id=NEW.post_id AND (visible_after>now() OR job_expires_at<=now() OR status<>'active')) THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_post_interest_visibility BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_post_interest_visibility();
REVOKE ALL ON FUNCTION public.require_active_actor(),public.guard_post_interest_visibility() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.admin_evidence_sender(_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result text; BEGIN IF NOT public.has_role(auth.uid(),'admin') OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT p.phone INTO result FROM public.profiles p JOIN public.post_sharing_evidence c ON c.user_id=p.id WHERE c.id=_id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_evidence_sender(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_evidence_sender(uuid) TO authenticated;